parameters.text:
=Research question: {{ $json.question }}
Depth: {{ $json.depth }}

Break this into 4 to 6 search queries that together cover the question. Each query must be phrased the way someone would actually type it into Google - short, concrete, no boolean operators. Cover different angles: current state, numbers and benchmarks, opposing views, and recent developments. Do not repeat the original question verbatim.

parameters.jsCode:
// Pull organic results out of every SERP response, dedupe by host+path, and drop
// the domains that never carry substance.
//
// NOTE: n8n's Code sandbox has no `URL` constructor (also no fetch/crypto/process),
// so hosts are parsed with a regex. Verified against this n8n build: the URL
// constructor throws ReferenceError, and swallowing that in a try/catch
// silently empties the whole run.
const SKIP = /(^|\.)(youtube|facebook|instagram|tiktok|pinterest|x)\.com$/i;

function splitUrl(link) {
  const m = String(link).match(/^https?:\/\/([^\/?#]+)([^?#]*)/i);
  if (!m) return null;
  return { host: m[1].replace(/^www\./i, '').toLowerCase(), path: m[2] || '/' };
}

const seen = new Set();
const out = [];
let serpCount = 0, unparsable = 0;

for (const item of $input.all()) {
  let payload = item.json.body ?? item.json;
  if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); }
    catch { unparsable++; continue; }
  }
  const organic = payload.organic ?? payload.organic_results ?? [];
  serpCount += organic.length;

  for (const r of organic) {
    const link = r.link || r.url;
    if (!link) continue;
    const u = splitUrl(link);
    if (!u || SKIP.test(u.host)) continue;
    const key = u.host + u.path;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ json: {
      url: link,
      host: u.host,
      title: r.title ?? '',
      snippet: r.description ?? r.snippet ?? '',
      rank: r.rank ?? r.position ?? null,
    }});
  }
}

if (out.length === 0) {
  // Say which stage actually failed instead of guessing at the cause.
  throw new Error(
    `No usable sources. Bright Data returned ${$input.all().length} response(s) ` +
    `carrying ${serpCount} organic result(s); ${unparsable} could not be parsed as JSON. ` +
    (serpCount === 0
      ? 'Zero organic results means the SERP zone name in Research Config does not match a zone in your Bright Data account, or the queries returned nothing.'
      : 'Results came back but every URL was filtered out - loosen the SKIP list.')
  );
}

return out;

// Strip markup, collapse whitespace, and cap each source so one bloated page
// cannot crowd the others out of the context window.
//
// Bright Data can answer HTTP 200 with a plain-text rate-limit notice instead of
// a page. Because the status is 200, n8n's retryOnFail never fires, so that case
// is detected here by body text and counted rather than silently dropped.
const PER_SOURCE_CHARS = 6000;
const MIN_USABLE_CHARS = 200;
const RATE_LIMITED = /rate limit has been applied|please retry in a few seconds/i;

const sources = $('Limit to Max Sources').all();
const out = [];
let rateLimited = 0, tooShort = 0;

$input.all().forEach((item, i) => {
  const meta = sources[i]?.json ?? {};
  let text = item.json.data ?? item.json.body ?? '';
  if (typeof text !== 'string') text = JSON.stringify(text);

  if (RATE_LIMITED.test(text)) { rateLimited++; return; }

  text = text
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (text.length < MIN_USABLE_CHARS) { tooShort++; return; }

  out.push({ json: {
    id: out.length + 1,
    url: meta.url ?? '',
    host: meta.host ?? '',
    title: meta.title ?? '',
    chars: text.length,
    text: text.slice(0, PER_SOURCE_CHARS),
  }});
});

if (rateLimited > 0) {
  console.log(`${rateLimited} page(s) were rate limited by Bright Data and skipped. Lower the batch size on the Web Unlocker node if this keeps happening.`);
}

if (out.length === 0) {
  throw new Error(
    `No readable pages. Of ${$input.all().length} fetch(es): ${rateLimited} rate limited, ` +
    `${tooShort} returned too little text. ` +
    (rateLimited > 0
      ? 'Rate limiting is the cause here - open the Web Unlocker node, Settings, Batching, and drop the batch size to 2 with a 2000ms interval.'
      : 'Check that the Web Unlocker zone name in Research Config matches a zone in your Bright Data account.')
  );
}

return out;

