// Staple the audit onto the report. Flagged claims stay visible - a reader
// who cannot see what failed has no way to judge what passed.
const cfg = $('Set Research Parameters').first().json;
const report = $('Compose Research Report').first().json.text ?? '';
// single-item input: the auditor runs on one report, so it emits one item.
const audit = $input.first().json.output ?? {};
const claims = audit.claims ?? [];
const sources = $('Aggregate to Create Corpus').first().json.sources ?? [];

const failed = claims.filter(c => c.verdict !== 'supported');
const supported = claims.length - failed.length;
const confidence = claims.length ? Math.round((supported / claims.length) * 100) : 0;

let flags = '';
if (failed.length) {
  flags = '\n\n## Flagged claims\n\n' + failed
    .map(c => `- **${c.verdict}** - ${c.claim}` + (c.evidence ? `\n  - checked against: ${c.evidence}` : ''))
    .join('\n');
} else {
  flags = '\n\n## Flagged claims\n\nNone. Every claim traced to a source.';
}

const header = `# ${cfg.question}\n\n` +
  `**Confidence:** ${confidence}% of claims verified (${supported}/${claims.length})  \n` +
  `**Sources read:** ${sources.length}  \n` +
  `**Depth:** ${cfg.depth}\n\n---\n\n`;

return [{
  json: {
    run_id: cfg.run_id,
    question: cfg.question,
    depth: cfg.depth,
    email: cfg.email,
    sources_read: sources.length,
    claims_total: claims.length,
    claims_supported: supported,
    claims_flagged: failed.length,
    confidence,
    report_markdown: header + report + flags,
    source_urls: sources.map(s => s.url).join(', '),
  },
}];
